include <robotics.scad>
// Ovonic O-50C-2200-3S1P-XT60 pack body (shrink-wrapped soft pack).
// Official envelope: L 105 (X) x W 33 (Y) x H 21 (Z) mm; tolerances L ±5, W ±2, H ±2.
// Lead end (main + balance leads) at +X; leads/plugs not modeled.
// Origin: bottom face center, label face up.
L = 105; W = 33; H = 21;
r_long = 2;   // long-edge rounding: NOT dimensioned by Ovonic, kept small/conservative
cuboid([L, W, H], rounding = r_long, edges = "X", anchor = BOT, $fn = 32);
